def validate_host(host: str) -> str:
    host = (host or '').strip()
    if not host:
        abort(400)
    if any((char in host for char in DANGEROUS_CHARS)):
        abort(400)
    try:
        ipaddress.ip_address(host)
        return host
    except ValueError:
        pass
    if not HOSTNAME_RE.fullmatch(host):
        abort(400)
    return host.rstrip('.')

